[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$relative=$PacketPath.Replace('\','/').Trim();if($relative.Contains('..')-or $relative -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($relative.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "Worker packet missing: $relative"};$p=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)))|ConvertFrom-Json;foreach($x in @('WorkerId','Version','TaskContract','PlanHash','AllowedRoots','ArgumentsSchema','Environment','SecretsPolicy','Timeout','Concurrency','Artifacts','Cancel','Recovery','RunRecord','Owner','StaleWhen')){if($null -eq $p.PSObject.Properties[$x]){throw "Worker field missing: $x"}};if([string]$p.PlanHash -notmatch '^[0-9a-fA-F]{64}$'){throw 'PlanHash must be SHA-256.'};if([string]$p.SecretsPolicy -notmatch '^(deny|redacted)$'){throw 'SecretsPolicy must be deny or redacted.'};if([int]$p.Timeout -lt 1-or [int]$p.Concurrency -lt 1){throw 'Timeout and Concurrency must be positive.'};if(@($p.AllowedRoots).Count -eq 0){throw 'AllowedRoots is required.'};foreach($path in @($p.AllowedRoots)){if([IO.Path]::IsPathRooted([string]$path)-or [string]$path -match '[*?]'){throw 'AllowedRoots must be bounded project-relative paths.'}};if([string]$p.TaskContract -eq 'missing'-or [string]$p.Cancel -eq 'unsupported'-or [string]$p.Recovery -eq 'none'){throw 'Worker packet must declare TaskContract, cancellation and recovery.'};Write-Output "PASS: managed Worker contract bounds authority, roots, secrets, timeout, cancellation and recovery: $relative"
